/* SPDX-License-Identifier: MIT. Copyright (c) 2026 Web Stylebook */

/*
 * Web Stylebook kit theme: Quiet Utility.
 *
 * Token contract. Every kit component reads only these --ws-* variables.
 * The same names exist in the light palette and the dark palette.
 *
 * Light: :root, and again on .light / [data-theme="light"] so a subtree can
 * force light inside a dark ancestor.
 * Dark: .dark / [data-theme="dark"] (the shadcn convention), and
 * @media (prefers-color-scheme: dark) on :root when the host has not forced
 * light. The media query is how a host that sets color-scheme follows the OS.
 * color-scheme is set with the palette so native controls match.
 *
 * Structural tokens (type, space, radius, motion, targets) are declared once
 * on :root. They do not change with the palette.
 *
 * Source of the light surfaces: .ported-style-page--quiet-utility. Values
 * marked "adjusted" differ from that source; the comment gives the reason.
 *
 * Fonts are not bundled. Load Inter (Latin) and Pretendard Variable (Korean):
 *   https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap
 *   https://cdn.jsdelivr.net/gh/orioncactus/pretendard/dist/web/variable/pretendardvariable-dynamic-subset.css
 */

:root {
  /* palette:light */
    color-scheme: light;
    --ws-color-canvas: #ffffff;
    --ws-color-surface: #edf2f4;
    --ws-color-surface-hover: #e5ebee;
    --ws-color-panel: #ffffff;
    --ws-color-inset: #f7f9fa;

    --ws-color-text: #1f2328;
    --ws-color-text-muted: #5d6772;

    --ws-color-divider: #bdc7cf;
    --ws-color-line: #7a848e;
    --ws-color-line-hover: #6e7a84;
    --ws-color-field-line: #68727c;

    --ws-color-accent: #526371;
    --ws-color-accent-hover: #1f2328;
    --ws-color-on-accent: #ffffff;
    --ws-color-focus: #526371;

    --ws-color-neutral-text: #424b55;
    --ws-color-neutral-tint: #dfe5ea;
    --ws-color-neutral-line: #b5c1cb;
    --ws-color-neutral-mark: #6f7b86;

    --ws-color-info-text: #0550ae;
    --ws-color-info-tint: #dcebfd;
    --ws-color-info-line: #a9c7ef;
    --ws-color-info-mark: #0969da;

    --ws-color-positive-text: #116329;
    --ws-color-positive-tint: #dcf0e2;
    --ws-color-positive-line: #99cba7;
    --ws-color-positive-mark: #1a7f37;

    --ws-color-caution-text: #7a4c00;
    --ws-color-caution-tint: #fbeccb;
    --ws-color-caution-line: #dbbb6c;
    --ws-color-caution-mark: #9a6700;

    --ws-color-critical-text: #a40e26;
    --ws-color-critical-tint: #fbe2e5;
    --ws-color-critical-line: #efb1b8;
    --ws-color-critical-mark: #cf222e;
  /* endpalette */

  /* Type. */
  --ws-font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --ws-font-mono: ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, monospace;
  --ws-text-xs: 0.75rem;
  --ws-text-sm: 0.8125rem;
  --ws-text-md: 0.875rem;
  --ws-text-lg: 0.9375rem;
  --ws-text-xl: 1rem;
  --ws-leading-tight: 1.3;
  --ws-leading: 1.55;
  --ws-weight-regular: 400;
  --ws-weight-medium: 500;
  --ws-weight-semibold: 600;
  --ws-tracking-label: 0.01em;
  --ws-tracking-title: -0.01em;

  /* Space, on a 4px grid. --ws-gap-label is the 6px step between a label and its control. */
  --ws-space-1: 4px;
  --ws-space-2: 8px;
  --ws-space-3: 12px;
  --ws-space-4: 16px;
  --ws-space-5: 20px;
  --ws-space-6: 24px;
  --ws-space-8: 32px;
  --ws-space-10: 40px;
  --ws-gap-label: 6px;

  /* Corners by role: small block, inner control, control, inner frame, outer frame, capsule. */
  --ws-radius-xs: 4px;
  --ws-radius-sm: 6px;
  --ws-radius-md: 8px;
  --ws-radius-lg: 12px;
  --ws-radius-xl: 16px;
  --ws-radius-full: 999px;

  /* Controls. adjusted: the source button (~37px) and input (~44px) differ;
     the kit uses one height so a field and a button line up. Touch screens
     get the 44px target. --ws-target-min is the smallest hit target (WCAG 2.5.8),
     and it grows to 44px for a coarse pointer. */
  --ws-control-height: 36px;
  --ws-target-min: 24px;
  --ws-icon-size: 16px;
  --ws-focus-width: 2px;
  --ws-focus-offset: 2px;

  /* Motion. 200ms matches the source transitions. The slow step is for
     something that travels: a filling bar, a toast arriving. */
  --ws-duration-fast: 120ms;
  --ws-duration: 200ms;
  --ws-duration-slow: 420ms;
  --ws-ease: cubic-bezier(0.2, 0, 0, 1);
}

/* adjusted: control edges need 3:1 on white and on the Shell surface #edf2f4.
   The source line #ccd6dd is 1.4:1 and reads as missing. field-line is the
   stronger boundary used by text inputs. */

:root:lang(ko) {
  --ws-font-sans: 'Inter', 'Pretendard Variable', 'Pretendard', 'Apple SD Gothic Neo', 'Malgun Gothic', sans-serif;
}

:root:lang(ja) {
  --ws-font-sans: 'Inter', 'Hiragino Sans', 'Hiragino Kaku Gothic ProN', 'Yu Gothic', 'Meiryo', sans-serif;
}

/* Hangul and kana need more leading than Latin at the same size. */
:root:lang(ko),
:root:lang(ja) {
  --ws-leading-tight: 1.4;
  --ws-leading: 1.65;
  --ws-tracking-title: 0em;
}

@media (pointer: coarse) {
  :root {
    --ws-control-height: 44px;
    --ws-target-min: 44px;
  }
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --ws-duration-fast: 0ms;
    --ws-duration: 0ms;
    --ws-duration-slow: 0ms;
  }
}

/* Dark palette. A cool slate, not an inversion of the light hex values.
   Text stays off-white so it does not halo. The accent lightens and the label
   on it becomes dark, because a dark slate fill disappears into the panel. */
@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-theme='light']) {
    /* palette:dark */
    color-scheme: dark;
    --ws-color-canvas: #12171c;
    --ws-color-surface: #1c242c;
    --ws-color-surface-hover: #26303a;
    --ws-color-panel: #181f26;
    --ws-color-inset: #0e1318;

    --ws-color-text: #e8eef3;
    --ws-color-text-muted: #9eacb8;

    --ws-color-divider: #4a5a68;
    --ws-color-line: #6d8090;
    --ws-color-line-hover: #7d90a0;
    --ws-color-field-line: #8ea0b0;

    --ws-color-accent: #8fa6b6;
    --ws-color-accent-hover: #a3b6c4;
    --ws-color-on-accent: #101418;
    --ws-color-focus: #c5d5e2;

    --ws-color-neutral-text: #d5dee6;
    --ws-color-neutral-tint: #2a343e;
    --ws-color-neutral-line: #5c6e7e;
    --ws-color-neutral-mark: #9aabba;

    --ws-color-info-text: #cfe4ff;
    --ws-color-info-tint: #1a3148;
    --ws-color-info-line: #4d739c;
    --ws-color-info-mark: #79b4f0;

    --ws-color-positive-text: #c8f0d4;
    --ws-color-positive-tint: #153024;
    --ws-color-positive-line: #3d7a56;
    --ws-color-positive-mark: #6dce8c;

    --ws-color-caution-text: #ffe3b0;
    --ws-color-caution-tint: #3a2e16;
    --ws-color-caution-line: #8a7040;
    --ws-color-caution-mark: #e2b15a;

    --ws-color-critical-text: #ffd0d4;
    --ws-color-critical-tint: #3c2228;
    --ws-color-critical-line: #a05a64;
    --ws-color-critical-mark: #ff8b96;
    /* endpalette */
  }
}

:is(.dark, [data-theme='dark']) {
  /* palette:dark */
    color-scheme: dark;
    --ws-color-canvas: #12171c;
    --ws-color-surface: #1c242c;
    --ws-color-surface-hover: #26303a;
    --ws-color-panel: #181f26;
    --ws-color-inset: #0e1318;

    --ws-color-text: #e8eef3;
    --ws-color-text-muted: #9eacb8;

    --ws-color-divider: #4a5a68;
    --ws-color-line: #6d8090;
    --ws-color-line-hover: #7d90a0;
    --ws-color-field-line: #8ea0b0;

    --ws-color-accent: #8fa6b6;
    --ws-color-accent-hover: #a3b6c4;
    --ws-color-on-accent: #101418;
    --ws-color-focus: #c5d5e2;

    --ws-color-neutral-text: #d5dee6;
    --ws-color-neutral-tint: #2a343e;
    --ws-color-neutral-line: #5c6e7e;
    --ws-color-neutral-mark: #9aabba;

    --ws-color-info-text: #cfe4ff;
    --ws-color-info-tint: #1a3148;
    --ws-color-info-line: #4d739c;
    --ws-color-info-mark: #79b4f0;

    --ws-color-positive-text: #c8f0d4;
    --ws-color-positive-tint: #153024;
    --ws-color-positive-line: #3d7a56;
    --ws-color-positive-mark: #6dce8c;

    --ws-color-caution-text: #ffe3b0;
    --ws-color-caution-tint: #3a2e16;
    --ws-color-caution-line: #8a7040;
    --ws-color-caution-mark: #e2b15a;

    --ws-color-critical-text: #ffd0d4;
    --ws-color-critical-tint: #3c2228;
    --ws-color-critical-line: #a05a64;
    --ws-color-critical-mark: #ff8b96;
  /* endpalette */
}

:is(.light, [data-theme='light']) {
  /* palette:light */
    color-scheme: light;
    --ws-color-canvas: #ffffff;
    --ws-color-surface: #edf2f4;
    --ws-color-surface-hover: #e5ebee;
    --ws-color-panel: #ffffff;
    --ws-color-inset: #f7f9fa;

    --ws-color-text: #1f2328;
    --ws-color-text-muted: #5d6772;

    --ws-color-divider: #bdc7cf;
    --ws-color-line: #7a848e;
    --ws-color-line-hover: #6e7a84;
    --ws-color-field-line: #68727c;

    --ws-color-accent: #526371;
    --ws-color-accent-hover: #1f2328;
    --ws-color-on-accent: #ffffff;
    --ws-color-focus: #526371;

    --ws-color-neutral-text: #424b55;
    --ws-color-neutral-tint: #dfe5ea;
    --ws-color-neutral-line: #b5c1cb;
    --ws-color-neutral-mark: #6f7b86;

    --ws-color-info-text: #0550ae;
    --ws-color-info-tint: #dcebfd;
    --ws-color-info-line: #a9c7ef;
    --ws-color-info-mark: #0969da;

    --ws-color-positive-text: #116329;
    --ws-color-positive-tint: #dcf0e2;
    --ws-color-positive-line: #99cba7;
    --ws-color-positive-mark: #1a7f37;

    --ws-color-caution-text: #7a4c00;
    --ws-color-caution-tint: #fbeccb;
    --ws-color-caution-line: #dbbb6c;
    --ws-color-caution-mark: #9a6700;

    --ws-color-critical-text: #a40e26;
    --ws-color-critical-tint: #fbe2e5;
    --ws-color-critical-line: #efb1b8;
    --ws-color-critical-mark: #cf222e;
  /* endpalette */
}

// SPDX-License-Identifier: MIT
// Copyright (c) 2026 Web Stylebook

/**
 * How a host selects the Quiet Utility palette.
 * The color values live in theme.css. This module is the selector contract
 * the site shell can reuse without parsing the stylesheet.
 */
export const kitThemeContract = {
  stylesheet: 'theme.css',
  light: {
    selectors: [':root', '.light', '[data-theme="light"]'],
  },
  dark: {
    media: '(prefers-color-scheme: dark)',
    selectors: ['.dark', '[data-theme="dark"]'],
  },
} as const;
